import pandas as pd
import numpy as np

# Reuse staged population grid and Conservation polygon data; do not overwrite authoritative variables.
spatial_specialist_pop_source_df = population_grid_1km_df_for_conservation if 'population_grid_1km_df_for_conservation' in globals() else pop_df
spatial_specialist_luz_source_df = conservation_land_use_zone_polygons_4326_df

# Identify geometry column without printing raw records.
spatial_specialist_luz_cols = list(spatial_specialist_luz_source_df.columns)
spatial_specialist_geom_col_candidates = [c for c in spatial_specialist_luz_cols if c.lower() in ("geometry", "geom", "wkb_geometry")]
spatial_specialist_geom_col = spatial_specialist_geom_col_candidates[0] if spatial_specialist_geom_col_candidates else spatial_specialist_luz_cols[-1]

from shapely.geometry import Point
try:
    from shapely import wkb, wkt
except Exception:
    wkb = wkt = None

def _spatial_specialist_to_shapely(g):
    if g is None or (isinstance(g, float) and np.isnan(g)):
        return None
    if hasattr(g, "geom_type"):
        return g
    if hasattr(g, "data") and wkb is not None:
        return wkb.loads(bytes(g.data))
    if isinstance(g, (bytes, bytearray, memoryview)) and wkb is not None:
        return wkb.loads(bytes(g))
    if isinstance(g, str):
        s = g.strip()
        if (s.startswith("POLYGON") or s.startswith("MULTIPOLYGON") or s.startswith("GEOMETRYCOLLECTION")) and wkt is not None:
            return wkt.loads(s)
        if wkb is not None:
            try:
                return wkb.loads(bytes.fromhex(s))
            except Exception:
                pass
    return None

spatial_specialist_conservation_geoms = [
    geom for geom in spatial_specialist_luz_source_df[spatial_specialist_geom_col].map(_spatial_specialist_to_shapely)
    if geom is not None and not geom.is_empty
]

# Build valid point set from staged population grid.
spatial_specialist_population_points_df = spatial_specialist_pop_source_df[["longitude", "latitude", "population"]].copy()
spatial_specialist_population_points_df = spatial_specialist_population_points_df.dropna(subset=["longitude", "latitude", "population"]).reset_index(drop=False)
spatial_specialist_population_points = [
    Point(float(lon), float(lat))
    for lon, lat in zip(spatial_specialist_population_points_df["longitude"], spatial_specialist_population_points_df["latitude"])
]

# Point-in-polygon join with duplicate prevention: each population row can contribute at most once.
try:
    from shapely.strtree import STRtree
    spatial_specialist_tree = STRtree(spatial_specialist_conservation_geoms)
    spatial_specialist_inside_mask = []
    for pt in spatial_specialist_population_points:
        candidates = spatial_specialist_tree.query(pt)
        # Shapely 2 returns integer indices; Shapely 1 returns geometries.
        if len(candidates) and isinstance(candidates[0], (int, np.integer)):
            inside = any(pt.within(spatial_specialist_conservation_geoms[int(i)]) for i in candidates)
        else:
            inside = any(pt.within(poly) for poly in candidates)
        spatial_specialist_inside_mask.append(inside)
except Exception:
    spatial_specialist_inside_mask = [
        any(pt.within(poly) for poly in spatial_specialist_conservation_geoms)
        for pt in spatial_specialist_population_points
    ]

spatial_specialist_inside_mask = np.array(spatial_specialist_inside_mask, dtype=bool)
spatial_specialist_conservation_grid_points_inside_df = spatial_specialist_population_points_df.loc[spatial_specialist_inside_mask].copy()
spatial_specialist_conservation_population_sum_unrounded = float(spatial_specialist_conservation_grid_points_inside_df["population"].sum())
spatial_specialist_conservation_population_rounded_int = int(round(spatial_specialist_conservation_population_sum_unrounded))

spatial_specialist_conservation_pip_summary = {
    "population_rows_checked": int(len(spatial_specialist_population_points_df)),
    "conservation_polygons_checked": int(len(spatial_specialist_conservation_geoms)),
    "unique_grid_points_inside_conservation": int(spatial_specialist_inside_mask.sum()),
    "population_sum_unrounded": spatial_specialist_conservation_population_sum_unrounded,
    "population_sum_rounded_int": spatial_specialist_conservation_population_rounded_int,
}

print("Point-in-polygon spatial join summary:")
for k, v in spatial_specialist_conservation_pip_summary.items():
    print(f"{k}: {v}")
